ALTER TABLE "calendar_events" ADD COLUMN "agenda" text;--> statement-breakpoint
ALTER TABLE "calendar_events" ADD COLUMN "attachments" jsonb DEFAULT '[]'::jsonb NOT NULL;--> statement-breakpoint
